import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';import {execFileSync} from 'node:child_process';import {hash,json} from './seal-simple-website-successor.mjs';
const stage='F:/VisibleMedicine/staging/20261025-nasal-bone-imaging-native',site=stage+'/atlas',clone=json(stage+'/CLONE.json'),alt=site+'/.git/objects/info/alternates';assert.equal(hash(stage+'/CLONE.json'),'fca234839d5fc594958a30b4b9a05a2c520caff2fbeddbbaf64447bbe325f252');assert.equal(clone.base.head,'27b341001718b7d5bb4f45aad0c8d8784e287c3b');const before=fs.readFileSync(alt,'utf8');
const visited=new Set(),visiting=new Set(),ordered=[],missing=[],cycles=[];
function walk(input){const resolved=path.resolve(input);if(!fs.existsSync(resolved)){missing.push(resolved);return;}const real=fs.realpathSync(resolved);if(visited.has(real))return;if(visiting.has(real)){cycles.push(real);return;}assert(fs.statSync(real).isDirectory());visiting.add(real);const file=path.join(real,'info','alternates');if(fs.existsSync(file))for(const line of fs.readFileSync(file,'utf8').split(/\r?\n/).filter(Boolean)){assert(!line.startsWith('"')&&!line.includes('\0'),'Unambiguous Git object path required');walk(path.resolve(real,line));}visiting.delete(real);visited.add(real);ordered.push(real.replaceAll('\\','/'));}
for(const line of before.split(/\r?\n/).filter(Boolean))walk(path.resolve(site+'/.git/objects',line));assert(ordered.length>1&&ordered.length<500);assert(!ordered.some(p=>path.resolve(p)===path.resolve(site+'/.git/objects')));
fs.writeFileSync(stage+'/GIT_ALTERNATES_BEFORE.txt',before,{flag:'wx'});fs.writeFileSync(alt,ordered.join('\n')+'\n');
const git=args=>execFileSync('git',['--no-replace-objects','-C',site,...args],{encoding:'utf8',windowsHide:true,maxBuffer:32e6,stdio:['pipe','pipe','pipe'],env:{...process.env,GIT_OPTIONAL_LOCKS:'0',GIT_NO_REPLACE_OBJECTS:'1'}});
try{
 assert.equal(git(['rev-parse','HEAD']).trim(),clone.base.head);assert.equal(git(['rev-parse','HEAD^{tree}']).trim(),clone.base.tree);assert.equal(git(['status','--porcelain','--untracked-files=all']).trim(),'');
 const tree=git(['ls-tree','-r','-z','HEAD']).split('\0').filter(Boolean).map(l=>{const [header,p]=l.split('\t'),[mode,type,oid]=header.split(' ');assert.equal(type,'blob');return {path:p,oid,mode};});
 const checked=execFileSync('git',['--no-replace-objects','-C',site,'cat-file','--batch-check'],{input:tree.map(r=>r.oid).join('\n')+'\n',encoding:'utf8',windowsHide:true,maxBuffer:32e6,stdio:['pipe','pipe','pipe']}).trim().split(/\r?\n/);assert.equal(checked.length,tree.length);for(let i=0;i<checked.length;i++){const [oid,type,size]=checked[i].split(' ');assert.equal(oid,tree[i].oid);assert.equal(type,'blob');assert(Number.isSafeInteger(Number(size)));}
 for(const r of [...clone.sourceRows,...clone.publicRows])assert.equal(hash(site+'/'+r.path),r.sha256,r.path);
 const receipt={schema:'vm-staged-git-reference-flattening/1',at:new Date().toISOString(),site,head:clone.base.head,tree:clone.base.tree,before:{path:stage+'/GIT_ALTERNATES_BEFORE.txt',sha256:hash(stage+'/GIT_ALTERNATES_BEFORE.txt')},afterSha256:hash(alt),objectStores:ordered.length,ancestorFirstOrdering:true,missingPaths:missing,prunedCycles:cycles,currentTreeBlobAvailabilityVerified:tree.length,allSourceAndAssetBytesUnchanged:true,otherRepositoriesOrOwnerCheckoutModified:false,fullAncestryOrStandaloneBackupClaimed:false};fs.writeFileSync(stage+'/GIT_REFERENCE_FIX.json',JSON.stringify(receipt,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({receipt:stage+'/GIT_REFERENCE_FIX.json',sha256:hash(stage+'/GIT_REFERENCE_FIX.json'),objectStores:ordered.length,treeBlobs:tree.length,missing:missing.length,cycles:cycles.length}));
}catch(e){fs.writeFileSync(alt,before);throw e;}
